import{j as e}from"./blog-pages-CSFOXFVG.js";import{I as a}from"./I18nErpPage-FFr5AJKw.js";import"./PillarHubNav-DMF97Kgh.js";import"./badge-BWInRu1H.js";const i={heroBadge:"Sistema de gestión de inspección END",heroTitle:"Software ERP de Ensayos No Destructivos en Ciudad de México",heroSubtitle:"Sistema integral de gestión de inspección",heroIntro:"ERP especializado para empresas de Ensayos No Destructivos (END) que operan en la Zona Metropolitana del Valle de México. Automatice el seguimiento de certificaciones ASNT, la programación de inspecciones API 510, API 570 y API 653, y la generación de reportes PDF en formato Pemex en minutos.",ctaPrimary:"Solicitar demostración para Ciudad de México",ctaSecondary:"English version",statCompanies:"Empresas END usando Atlantis ERP",statRating:"Calificación promedio de clientes",statAdminReduction:"Reducción en tiempo administrativo",statModules:"Módulos centrales para END",marketContextLabel:"Contexto del mercado END",painPointsTitle:"Por qué los equipos END en Ciudad de México eligen Atlantis ERP",painPointsSubtitle:"Tres puntos críticos de operación eliminados desde el día uno de la implementación",problemLabel:"El problema",solutionLabel:"La solución",modulesTitle:"Seis módulos centrales para empresas de inspección END",modulesSubtitle:"Cada módulo está diseñado específicamente para la industria de inspección — no es software genérico de negocios renombrado",roiTitle:"ROI de Atlantis ERP en Ciudad de México",faqTitle:"Preguntas frecuentes — Atlantis NDT ERP en Ciudad de México",alsoServingTitle:"También servimos",finalCtaTitle:"¿Listo para modernizar sus operaciones END en Ciudad de México?",finalCtaBody:"Únase a las empresas de inspección en CDMX, Tula, Salamanca y Coatzacoalcos que han reemplazado hojas de cálculo y registros en papel con Atlantis NDT ERP. Solicite una demostración personalizada.",finalCtaPrimary:"Solicitar demostración",finalCtaSecondary:"View English version",switchLangLabel:"English version"};function t(){return e.jsx(a,{lang:"es",dir:"ltr",city:"Ciudad de México",countryCode:"MX",countryName:"México",slug:"ndt-erp-mexico-city",canonicalPath:"/es/ndt-erp-mexico-city",englishPath:"/ndt-erp-mexico-city",pageTitle:"Software ERP END en Ciudad de México | Gestión de Inspección Industrial | Atlantis NDT",pageDescription:"Software ERP de Ensayos No Destructivos para empresas de inspección en Ciudad de México. Automatice el seguimiento de certificaciones ASNT, programación API 510/570/653 y generación de reportes en formato Pemex.",keywords:"software END Ciudad de México, ERP ensayos no destructivos, ASNT certificación, API 510, Pemex inspección, NOM-020-STPS, CDMX inspección industrial",marketContext:"La Ciudad de México opera como el centro administrativo y financiero del sector industrial mexicano, albergando las oficinas centrales de Petróleos Mexicanos (Pemex), la Comisión Reguladora de Energía y las principales empresas de inspección que dan servicio a refinerías como Tula de Allende y Salamanca, así como al complejo petroquímico de Coatzacoalcos. Las empresas de Ensayos No Destructivos (END) que operan desde CDMX deben cumplir simultáneamente con las normas oficiales mexicanas NOM-020-STPS para equipos sometidos a presión y NOM-009-STPS para trabajos en altura, además de los requisitos específicos de Pemex Refinación y Pemex Transformación Industrial para calificación de inspectores. Atlantis NDT ERP proporciona a los equipos de inspección en Ciudad de México una plataforma unificada para el seguimiento de certificaciones ASNT SNT-TC-1A e ISO 9712, la programación automatizada de inspecciones según API 510 para recipientes a presión, API 570 para tuberías y API 653 para tanques de almacenamiento, así como la generación de reportes PDF bilingües (español e inglés) compatibles con los formatos requeridos por la Agencia Nacional de Seguridad Industrial y de Protección al Medio Ambiente (ASEA) y los estándares internos de Pemex.",roiBody:"Los clientes de Atlantis NDT ERP en Ciudad de México reportan una reducción del 40% en tiempo administrativo durante los primeros seis meses de despliegue, junto con la disminución del tiempo de elaboración de un reporte API 510 de cuatro horas a menos de cinco minutos. Los incidentes de caducidad de certificaciones ASNT desaparecen gracias a las alertas automáticas a 90, 60 y 30 días, y la preparación de paquetes de auditoría para revisiones de Pemex y ASEA pasa de varios días a un solo clic. Para un equipo de inspección de doce técnicos en CDMX, esto representa un ahorro anual estimado entre 380.000 y 520.000 pesos mexicanos en sobrecarga administrativa recuperable, antes de contabilizar el valor preventivo de evitar la pérdida de elegibilidad para contratos con Pemex.",painPoints:[{title:"Cumplimiento simultáneo con Pemex y ASEA",problem:"Las empresas de inspección en CDMX que sirven a Pemex deben cumplir simultáneamente con los formatos de reporte internos de Pemex Refinación, los requisitos regulatorios de ASEA y las normas oficiales mexicanas NOM-020-STPS, lo cual es prácticamente imposible de gestionar manualmente.",solution:"Atlantis ERP incluye plantillas pre-aprobadas para los formatos de Pemex y ASEA, con actualización automática cuando se emiten nuevas versiones de las normas, garantizando el cumplimiento continuo y la elegibilidad como proveedor."},{title:"Caducidad inesperada de certificaciones",problem:"Los técnicos certificados en CDMX que trabajan en refinerías de Tula y Salamanca pierden elegibilidad cuando sus certificaciones ASNT, ISO 9712 o calificaciones de Pemex caducan sin previo aviso, suspendiendo las movilizaciones a campo.",solution:"El sistema rastrea automáticamente cada calificación y envía alertas por correo electrónico a 90, 60 y 30 días tanto al técnico como a su supervisor, eliminando las auditorías manuales en hojas de cálculo antes de cada movilización."},{title:"Generación manual de reportes en formato Pemex",problem:"Los equipos de inspección en Ciudad de México invierten entre tres y cuatro horas en reformatear manualmente cada reporte API 570 al formato interno de Pemex Refinación, tiempo que podría dedicarse a trabajo técnico de valor agregado.",solution:"Genere un reporte completo en formato Pemex con su logotipo corporativo y firma digital en menos de cinco minutos directamente desde los datos capturados en campo, sin reformateo manual ni errores de copia."}],modules:[{title:"Programación de inspección y gestión de órdenes de trabajo",description:"Automatice el cálculo de intervalos de inspección según API 510, API 570, API 653 y los intervalos de inspección basada en riesgo (RBI) especificados por Pemex. Asigne técnicos, equipos y procedimientos a órdenes de trabajo en segundos.",features:["Cálculo automático de intervalos API 510/570/653","Programación de inspección basada en riesgo (RBI)","Matriz de disponibilidad de técnicos","Flujos de aprobación de órdenes de trabajo","Acceso móvil para inspectores en campo"]},{title:"Seguimiento de certificaciones del personal END",description:"Centralice registros de certificaciones ASNT SNT-TC-1A, ISO 9712, calificaciones específicas de Pemex y NOM-020-STPS. Reciba alertas automáticas a 90, 60 y 30 días antes del vencimiento.",features:["Alertas de vencimiento ASNT Nivel I/II/III","Seguimiento ISO 9712 y calificaciones Pemex","Matriz de calificaciones por cliente","Recordatorios automáticos de renovación","Exportación PDF lista para auditoría"]},{title:"Generación de reportes de inspección",description:"Genere reportes profesionales en PDF según API 510, API 570, API 653, ASME Sección VIII y formatos específicos de Pemex directamente desde los datos capturados en campo — sin reformateo manual.",features:["Plantillas API 510 para recipientes a presión","Formatos API 570 para inspección de tuberías","Reportes API 653 para tanques de almacenamiento","Constructor de plantillas personalizadas Pemex","Integración de firma digital y sello"]},{title:"Gestión de datos de corrosión",description:"Registre mediciones de espesor, tasas de corrosión y cálculos de vida remanente en todos los activos. Visualice tendencias de degradación con gráficos codificados por color.",features:["Base de datos de mediciones de espesor por ultrasonido","Gráficos de tendencia de tasa de corrosión","Cálculo de vida remanente y fecha de retiro","Alertas de porcentaje de pérdida de pared","Exportación de evaluación API 579 fitness-for-service"]},{title:"Registro de activos y gestión de equipos",description:"Mantenga un registro digital completo que cubra recipientes a presión, circuitos de tuberías y tanques de almacenamiento en refinerías de Pemex. Rastree el estado de calibración de equipos de inspección.",features:["Jerarquía de activos vinculada a P&ID","Rastreador de fechas de calibración","Etiquetado de activos con códigos QR","Historial de inspección por activo","Clasificación de riesgo y criticidad"]},{title:"Tablero de cumplimiento",description:"Visibilidad en tiempo real del cumplimiento con normativas API, ASME, ASEA y NOM mexicanas en todos los proyectos activos.",features:["Tablero de alertas de inspecciones vencidas","Vista general de cumplimiento multi-cliente","KPIs: entregas a tiempo, tasas de NCR","Alertas de cambios regulatorios","Reportes ejecutivos a nivel directivo"]}],integrations:["Formatos de reporte Pemex Refinación","Cumplimiento NOM-020-STPS y NOM-009-STPS","Reportes ASEA","Integración SAP S/4HANA PM","Plantillas IMP para integridad mecánica","Calificación de inspectores Pemex","Exportación a IBM Maximo CMMS","Registros para ANSI/API 1160 de integridad de ductos"],faqs:[{question:"¿El sistema soporta los formatos de reporte específicos de Pemex Refinación?",answer:"Sí. Atlantis NDT ERP incluye plantillas pre-aprobadas para los formatos de reporte requeridos por Pemex Refinación y Pemex Transformación Industrial, incluyendo reportes API 510 para recipientes a presión y API 570 para inspección de tuberías. Las plantillas se actualizan automáticamente cuando Pemex emite nuevas versiones de sus requisitos internos, garantizando que su empresa mantenga la elegibilidad como proveedor."},{question:"¿Cómo maneja el sistema los requisitos de la ASEA?",answer:"El módulo de cumplimiento incluye seguimiento completo de la documentación requerida por la Agencia Nacional de Seguridad Industrial y de Protección al Medio Ambiente (ASEA), incluyendo NOM-020-STPS para equipos sometidos a presión. El sistema mantiene un registro auditable que incluye fecha de cada medición de espesor, identificación del técnico ejecutor, referencia al procedimiento aprobado y estado de calibración del equipo utilizado."},{question:"¿Funciona el sistema sin conexión en plataformas marinas del Golfo de México?",answer:"Sí. La aplicación incluye modo de captura de datos sin conexión para trabajo en plataformas marinas en la Sonda de Campeche y otras operaciones offshore de Pemex Exploración y Producción. Los datos se sincronizan automáticamente cuando se restablece la conexión, garantizando que no se pierda información de inspección incluso en entornos con conectividad intermitente."},{question:"¿El sistema genera reportes bilingües español-inglés?",answer:"Sí. El sistema soporta la generación de reportes bilingües en el mismo archivo PDF, lo cual es requerido por varios clientes corporativos en México que reportan a casas matrices en Estados Unidos. También es posible generar reportes solo en español o solo en inglés según las necesidades del cliente."},{question:"¿Cuál es el tiempo de implementación para una empresa de inspección en CDMX?",answer:"El tiempo típico de implementación para una empresa de inspección en Ciudad de México es de cuatro a seis semanas, incluyendo la migración de datos históricos, capacitación de los equipos en español y la integración de las plantillas de reporte específicas de Pemex. Nuestro equipo de implementación ofrece capacitación en sitio en CDMX para asegurar la adopción rápida por parte de los técnicos de campo."}],ui:i})}export{t as default};
